package com.productpromo;

import android.content.*;
import android.database.Cursor;
import android.graphics.*;
import android.media.*;
import android.net.Uri;
import android.opengl.*;
import android.os.Environment;
import android.provider.MediaStore;
import android.view.Surface;
import java.io.*;
import java.nio.*;
import java.util.*;
import java.util.concurrent.CancellationException;

/** Offline AVC/AAC renderer. EGL timestamps each frame before MediaMuxer writes it. */
public class VideoExporter extends Thread {
    public interface Listener { void onProgress(int p); void onDone(Uri uri); void onError(String error); }
    private static final int WIDTH=720, HEIGHT=1280, FPS=30;
    private final Context context; private final ArrayList<Uri> imageUris; private final Uri music;
    private final int seconds; private final String name, price, tagline, features, howTo, note; private final Listener listener;
    private volatile boolean cancelled; private int encodedFrames; private int lastOutputIndex;
    private static class AudioData { MediaFormat format; ArrayList<Sample> samples=new ArrayList<>(); }
    private static class Sample { ByteBuffer data; MediaCodec.BufferInfo info; }
    VideoExporter(Context c,ArrayList<Uri> images,Uri audio,int duration,String n,String p,String t,String f,String h,String no,Listener l){context=c;imageUris=new ArrayList<>(images);music=audio;seconds=duration;name=n;price=p;tagline=t;features=f;howTo=h;note=no;listener=l;}
    public void cancel(){cancelled=true;}
    @Override public void run(){MediaCodec codec=null;MediaMuxer muxer=null;File temp=null;Uri saved=null;try{
        int requestedFrames=seconds*FPS;codec=MediaCodec.createEncoderByType("video/avc");MediaFormat vf=MediaFormat.createVideoFormat("video/avc",WIDTH,HEIGHT);vf.setInteger(MediaFormat.KEY_COLOR_FORMAT,MediaCodecInfo.CodecCapabilities.COLOR_FormatSurface);vf.setInteger(MediaFormat.KEY_BIT_RATE,6500000);vf.setInteger(MediaFormat.KEY_FRAME_RATE,FPS);vf.setInteger(MediaFormat.KEY_I_FRAME_INTERVAL,2);codec.configure(vf,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);Surface input=codec.createInputSurface();codec.start();
        AudioData audio=music==null?null:prepareAudio();temp=new File(context.getCacheDir(),"productpromo_"+System.currentTimeMillis()+".mp4");muxer=new MediaMuxer(temp.getAbsolutePath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);EglFrameRenderer renderer=new EglFrameRenderer(input,imageUris,name,price,tagline,features,howTo,note,context);MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();int videoTrack=-1,audioTrack=-1;boolean muxStarted=false;
        for(int frame=0;frame<requestedFrames&&!cancelled;frame++){renderer.draw(frame,requestedFrames);while(true){int out=codec.dequeueOutputBuffer(info,10000);if(out==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){if(muxStarted)throw new IOException("encoder format changed twice");videoTrack=muxer.addTrack(codec.getOutputFormat());if(audio!=null)audioTrack=muxer.addTrack(audio.format);muxer.start();muxStarted=true;if(audio!=null)for(Sample sample:audio.samples)muxer.writeSampleData(audioTrack,sample.data,sample.info);}else if(out>=0){lastOutputIndex=out;writeVideoSample(codec,muxer,videoTrack,info,muxStarted);codec.releaseOutputBuffer(out,false);}else break;}if(frame%3==0)listener.onProgress(frame*100/requestedFrames);}
        renderer.release();if(cancelled)throw new CancellationException();codec.signalEndOfInputStream();boolean eos=false;while(!eos){int out=codec.dequeueOutputBuffer(info,10000);if(out==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){if(muxStarted)throw new IOException("encoder format changed twice");videoTrack=muxer.addTrack(codec.getOutputFormat());if(audio!=null)audioTrack=muxer.addTrack(audio.format);muxer.start();muxStarted=true;if(audio!=null)for(Sample sample:audio.samples)muxer.writeSampleData(audioTrack,sample.data,sample.info);}else if(out>=0){lastOutputIndex=out;writeVideoSample(codec,muxer,videoTrack,info,muxStarted);eos=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;codec.releaseOutputBuffer(out,false);}}
        if(encodedFrames!=requestedFrames)throw new IOException("encoded frame count "+encodedFrames+" / "+requestedFrames);muxer.stop();muxer.release();muxer=null;codec.stop();codec.release();codec=null;saved=saveToGallery(temp);temp.delete();temp=null;Verification verification=verify(saved,seconds,music!=null);if(!verification.ok){context.getContentResolver().delete(saved,null,null);throw new IOException(verification.error);}android.util.Log.i("ProductPromo","output URI "+saved+" file size "+verification.size+" video MIME "+verification.mime+" video duration "+verification.durationUs+" video track count "+verification.videoTracks+" audio track count "+verification.audioTracks+" encoded frame count "+verification.frames);listener.onProgress(100);listener.onDone(saved);
    }catch(CancellationException e){cleanup(temp,muxer,codec,saved);listener.onError("Export failed: cancelled");}catch(Exception e){cleanup(temp,muxer,codec,saved);listener.onError("Export failed: "+(e.getMessage()==null?e.getClass().getSimpleName():e.getMessage()));}}
    private void writeVideoSample(MediaCodec codec,MediaMuxer muxer,int track,MediaCodec.BufferInfo info,boolean started){if(started&&info.size>0&&(info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)==0){muxer.writeSampleData(track,codec.getOutputBuffer(lastOutputIndex),info);encodedFrames++;}}
    private AudioData prepareAudio()throws Exception{MediaExtractor ex=new MediaExtractor();ex.setDataSource(context,music,null);int track=-1;MediaFormat source=null;for(int n=0;n<ex.getTrackCount();n++){MediaFormat f=ex.getTrackFormat(n);String mime=f.getString(MediaFormat.KEY_MIME);if(mime!=null&&mime.startsWith("audio/")){track=n;source=f;break;}}if(track<0){ex.release();throw new IOException("selected file has no audio track");}String mime=source.getString(MediaFormat.KEY_MIME);android.util.Log.i("ProductPromo","selected audio MIME "+mime+" codec "+source);if("audio/mp4a-latm".equals(mime)){AudioData direct=readAacSamples(ex,track,source);ex.release();return direct;}AudioData encoded=transcodeAudio(ex,track,source);ex.release();return encoded;}
    private AudioData readAacSamples(MediaExtractor ex,int track,MediaFormat format)throws Exception{ex.selectTrack(track);AudioData result=new AudioData();result.format=format;while(ex.getSampleTime()>=0&&ex.getSampleTime()<seconds*1000000L){int size=(int)ex.getSampleSize();if(size<=0)break;ByteBuffer src=ByteBuffer.allocate(size);ex.readSampleData(src,0);src.flip();Sample s=new Sample();s.data=src;s.info=new MediaCodec.BufferInfo();s.info.set(0,size,ex.getSampleTime(),ex.getSampleFlags());result.samples.add(s);ex.advance();}return result;}
    private AudioData transcodeAudio(MediaExtractor extractor,int track,MediaFormat source)throws Exception{MediaCodec decoder=MediaCodec.createDecoderByType(source.getString(MediaFormat.KEY_MIME));extractor.selectTrack(track);decoder.configure(source,null,null,0);decoder.start();MediaCodec encoder=null;AudioData result=new AudioData();boolean inputDone=false,decoderDone=false,encoderDone=false;long pcmPts=0;MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();while(!encoderDone){if(!inputDone){int input=decoder.dequeueInputBuffer(10000);if(input>=0){ByteBuffer buffer=decoder.getInputBuffer(input);buffer.clear();long pts=extractor.getSampleTime();int size=pts<0?-1:extractor.readSampleData(buffer,0);if(size<0){decoder.queueInputBuffer(input,0,0,0,MediaCodec.BUFFER_FLAG_END_OF_STREAM);inputDone=true;}else{decoder.queueInputBuffer(input,0,size,pts,extractor.getSampleFlags());extractor.advance();}}}int output=decoder.dequeueOutputBuffer(info,10000);if(output==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){MediaFormat pcm=decoder.getOutputFormat();int rate=pcm.containsKey(MediaFormat.KEY_SAMPLE_RATE)?pcm.getInteger(MediaFormat.KEY_SAMPLE_RATE):44100;int channels=pcm.containsKey(MediaFormat.KEY_CHANNEL_COUNT)?pcm.getInteger(MediaFormat.KEY_CHANNEL_COUNT):2;encoder=MediaCodec.createEncoderByType("audio/mp4a-latm");MediaFormat af=MediaFormat.createAudioFormat("audio/mp4a-latm",rate,channels);af.setInteger(MediaFormat.KEY_AAC_PROFILE,MediaCodecInfo.CodecProfileLevel.AACObjectLC);af.setInteger(MediaFormat.KEY_BIT_RATE,128000);af.setInteger(MediaFormat.KEY_MAX_INPUT_SIZE,16384);encoder.configure(af,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);encoder.start();}else if(output>=0){if(info.size>0&&encoder!=null){ByteBuffer pcm=decoder.getOutputBuffer(output);int input=encoder.dequeueInputBuffer(10000);if(input>=0){ByteBuffer target=encoder.getInputBuffer(input);target.clear();pcm.position(info.offset);pcm.limit(info.offset+info.size);target.put(pcm);encoder.queueInputBuffer(input,0,info.size,pcmPts,0);pcmPts+=info.size*1000000L/(Math.max(1,source.containsKey(MediaFormat.KEY_SAMPLE_RATE)?source.getInteger(MediaFormat.KEY_SAMPLE_RATE):44100)*2*Math.max(1,source.containsKey(MediaFormat.KEY_CHANNEL_COUNT)?source.getInteger(MediaFormat.KEY_CHANNEL_COUNT):2));}}boolean end=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;decoder.releaseOutputBuffer(output,false);if(end){decoderDone=true;if(encoder!=null){int input=encoder.dequeueInputBuffer(10000);if(input>=0)encoder.queueInputBuffer(input,0,0,pcmPts,MediaCodec.BUFFER_FLAG_END_OF_STREAM);}}}if(encoder!=null){while(true){int out=encoder.dequeueOutputBuffer(info,0);if(out==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED)result.format=encoder.getOutputFormat();else if(out>=0){if(info.size>0&&(info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)==0){ByteBuffer encoded=encoder.getOutputBuffer(out).duplicate();encoded.position(info.offset);encoded.limit(info.offset+info.size);Sample sample=new Sample();sample.data=ByteBuffer.allocate(info.size);sample.data.put(encoded);sample.data.flip();sample.info=new MediaCodec.BufferInfo();sample.info.set(0,info.size,info.presentationTimeUs,info.flags);result.samples.add(sample);}encoderDone=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;encoder.releaseOutputBuffer(out,false);}else break;}}if(decoderDone&&encoder==null)throw new IOException("audio decoder produced no PCM");}decoder.stop();decoder.release();if(encoder!=null){encoder.stop();encoder.release();}if(result.format==null||result.samples.isEmpty())throw new IOException("audio transcode produced no AAC samples");return result;}
    private Uri saveToGallery(File file)throws Exception{ContentValues v=new ContentValues();v.put(MediaStore.Video.Media.DISPLAY_NAME,"ProductPromo_"+System.currentTimeMillis()+".mp4");v.put(MediaStore.Video.Media.MIME_TYPE,"video/mp4");v.put(MediaStore.Video.Media.RELATIVE_PATH,Environment.DIRECTORY_MOVIES+"/ProductPromo");v.put(MediaStore.Video.Media.IS_PENDING,1);Uri uri=context.getContentResolver().insert(MediaStore.Video.Media.EXTERNAL_CONTENT_URI,v);if(uri==null)throw new IOException("MediaStore insert failed");try(OutputStream out=context.getContentResolver().openOutputStream(uri);InputStream in=new FileInputStream(file)){byte[] b=new byte[65536];for(int n;(n=in.read(b))!=-1;)out.write(b,0,n);}ContentValues ready=new ContentValues();ready.put(MediaStore.Video.Media.IS_PENDING,0);context.getContentResolver().update(uri,ready,null,null);return uri;}
    private static class Verification{boolean ok;long size,durationUs;String mime,error;int videoTracks,audioTracks,frames;}
    private Verification verify(Uri uri,int expectedSeconds,boolean requireAudio)throws Exception{Verification v=new Verification();Cursor c=context.getContentResolver().query(uri,new String[]{MediaStore.Video.Media.SIZE,MediaStore.Video.Media.MIME_TYPE},null,null,null);if(c==null||!c.moveToFirst())throw new IOException("MediaStore query failed");v.size=c.getLong(0);v.mime=c.getString(1);c.close();MediaExtractor ex=new MediaExtractor();ex.setDataSource(context,uri,null);int video=-1;boolean hasAac=false;for(int n=0;n<ex.getTrackCount();n++){String m=ex.getTrackFormat(n).getString(MediaFormat.KEY_MIME);if(m.startsWith("video/"))v.videoTracks++;if(m.startsWith("audio/")){v.audioTracks++;if("audio/mp4a-latm".equals(m))hasAac=true;}if("video/avc".equals(m))video=n;}if(video<0)throw new IOException("verification missing video/avc");if(requireAudio&&!hasAac)throw new IOException("verification missing audio/mp4a-latm");ex.selectTrack(video);while(ex.getSampleTime()>=0){v.frames++;ex.advance();}v.durationUs=ex.getTrackFormat(video).getLong(MediaFormat.KEY_DURATION);ex.release();v.ok=v.size>0&&"video/mp4".equals(v.mime)&&v.durationUs>=((expectedSeconds-1)*1000000L)&&v.durationUs<=((expectedSeconds+1)*1000000L)&&v.frames>=expectedSeconds*FPS-2;v.error=v.ok?null:"verification failed size="+v.size+" mime="+v.mime+" durationUs="+v.durationUs+" frames="+v.frames;return v;}
    private void cleanup(File file,MediaMuxer muxer,MediaCodec codec,Uri uri){try{if(muxer!=null)muxer.release();}catch(Exception ignored){}try{if(codec!=null)codec.release();}catch(Exception ignored){}if(file!=null)file.delete();if(uri!=null)context.getContentResolver().delete(uri,null,null);}
    private static class EglFrameRenderer{
        private final EGLDisplay display; private final EGLSurface eglSurface; private final EGLContext eglContext;
        private final Bitmap frameBitmap; private final Canvas canvas; private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);
        private final ArrayList<Bitmap> images=new ArrayList<>(); private final String name,price,tagline,features,howTo,note;
        private final int program,texture; private final FloatBuffer vertices=ByteBuffer.allocateDirect(8*4).order(ByteOrder.nativeOrder()).asFloatBuffer();
        private final FloatBuffer texCoords=ByteBuffer.allocateDirect(8*4).order(ByteOrder.nativeOrder()).asFloatBuffer();
        private final int safeX=54, safeTop=92, safeBottom=112;
        EglFrameRenderer(Surface surface,ArrayList<Uri> uris,String n,String p,String t,String f,String h,String no,Context c)throws Exception{
            name=n;price=p;tagline=t;features=f;howTo=h;note=no;
            for(Uri u:uris){Bitmap b=BitmapFactory.decodeStream(c.getContentResolver().openInputStream(u));if(b!=null)images.add(b);}
            if(images.isEmpty())throw new IOException("no decodable images");
            display=EGL14.eglGetDisplay(EGL14.EGL_DEFAULT_DISPLAY);EGL14.eglInitialize(display,new int[2],0,new int[2],0);
            int[] cfg={EGL14.EGL_RED_SIZE,8,EGL14.EGL_GREEN_SIZE,8,EGL14.EGL_BLUE_SIZE,8,EGL14.EGL_ALPHA_SIZE,8,EGL14.EGL_RENDERABLE_TYPE,EGL14.EGL_OPENGL_ES2_BIT,0x3142,1,EGL14.EGL_NONE};
            EGLConfig[] out=new EGLConfig[1];EGL14.eglChooseConfig(display,cfg,0,out,0,1,new int[1],0);eglContext=EGL14.eglCreateContext(display,out[0],EGL14.EGL_NO_CONTEXT,new int[]{EGL14.EGL_CONTEXT_CLIENT_VERSION,2,EGL14.EGL_NONE},0);
            eglSurface=EGL14.eglCreateWindowSurface(display,out[0],surface,new int[]{EGL14.EGL_NONE},0);EGL14.eglMakeCurrent(display,eglSurface,eglSurface,eglContext);
            frameBitmap=Bitmap.createBitmap(WIDTH,HEIGHT,Bitmap.Config.ARGB_8888);canvas=new Canvas(frameBitmap);
            program=program("attribute vec4 a;attribute vec2 t;varying vec2 v;void main(){gl_Position=a;v=t;}","precision mediump float;uniform sampler2D s;varying vec2 v;void main(){gl_FragColor=texture2D(s,v);}");
            int[] tx=new int[1];GLES20.glGenTextures(1,tx,0);texture=tx[0];GLES20.glBindTexture(GLES20.GL_TEXTURE_2D,texture);GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D,GLES20.GL_TEXTURE_MIN_FILTER,GLES20.GL_LINEAR);GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D,GLES20.GL_TEXTURE_MAG_FILTER,GLES20.GL_LINEAR);
        }
        private int program(String vs,String fs){int v=GLES20.glCreateShader(GLES20.GL_VERTEX_SHADER);GLES20.glShaderSource(v,vs);GLES20.glCompileShader(v);int f=GLES20.glCreateShader(GLES20.GL_FRAGMENT_SHADER);GLES20.glShaderSource(f,fs);GLES20.glCompileShader(f);int p=GLES20.glCreateProgram();GLES20.glAttachShader(p,v);GLES20.glAttachShader(p,f);GLES20.glLinkProgram(p);return p;}
        private ArrayList<String> lines(String text,float size,float maxWidth,int maxLines){ArrayList<String> out=new ArrayList<>();if(text==null)text="";StringBuilder line=new StringBuilder();paint.setTextSize(size);for(int i=0;i<text.length();){int cp=text.codePointAt(i);String ch=new String(Character.toChars(cp));i+=Character.charCount(cp);if("\n".equals(ch)){out.add(line.toString().trim());line.setLength(0);continue;}String candidate=line+ch;if(paint.measureText(candidate)>maxWidth&&line.length()>0){out.add(line.toString().trim());line=new StringBuilder(ch.trim());}else line.append(ch);}if(line.length()>0)out.add(line.toString().trim());if(out.size()>maxLines){out=new ArrayList<>(out.subList(0,maxLines));String last=out.get(maxLines-1);out.set(maxLines-1,last+"…");}return out;}
        private float fitText(String text,float maxWidth,int maxLines,float start){for(float size=start;size>=24;size-=2)if(lines(text,size,maxWidth,maxLines).size()<=maxLines)return size;return 24;}
        private String[] featureList(){String[] raw=(features==null?new String[0]:features.split("\\n"));ArrayList<String> clean=new ArrayList<>();for(String x:raw)if(!x.trim().isEmpty())clean.add(x.trim());return clean.toArray(new String[0]);}
        private void drawTextBlock(String text,float x,float y,float width,int maxLines,float start,int color){float size=fitText(text,width,maxLines,start);paint.setTextSize(size);paint.setColor(color);paint.setTypeface(Typeface.DEFAULT_BOLD);paint.setTextAlign(Paint.Align.LEFT);float lineHeight=size*1.28f;for(String line:lines(text,size,width,maxLines)){canvas.drawText(line,x,y,paint);y+=lineHeight;}}
        private void drawImage(Bitmap source,int scene,float phase){canvas.drawColor(Color.rgb(18,23,30));float srcRatio=source.getWidth()/(float)source.getHeight(),dstRatio=WIDTH/(float)HEIGHT;float scale=srcRatio>dstRatio?WIDTH/(float)source.getWidth():HEIGHT/(float)source.getHeight();float w=source.getWidth()*scale,h=source.getHeight()*scale;float dx=(WIDTH-w)/2,dy=(HEIGHT-h)/2;int motion=scene%4;if(motion==0){float z=1f+.035f*phase;w*=z;h*=z;dx=(WIDTH-w)/2;dy=(HEIGHT-h)/2;}else if(motion==1){dx+=(phase-.5f)*Math.min(34f,Math.abs(WIDTH-w)/2f); }else if(motion==2){dx-=(phase-.5f)*Math.min(34f,Math.abs(WIDTH-w)/2f);}else{float z=1f+.018f*phase;w*=z;h*=z;dx=(WIDTH-w)/2;dy=(HEIGHT-h)/2;}canvas.drawBitmap(source,null,new RectF(dx,dy,dx+w,dy+h),paint);}
        private String sceneText(int scene){String[] fs=featureList();if(scene==0)return tagline;if(scene==1&&fs.length>0)return fs[0];if(scene==2&&fs.length>1)return fs[1];if(scene==3&&fs.length>2)return fs[2];if(scene==4)return howTo;if(scene==5)return note;if(fs.length>0)return fs[(scene-6)%fs.length];return tagline;}
        void draw(int frame,int total){int count=images.size();int index=Math.min(count-1,(int)((long)frame*count/Math.max(1,total)));int sceneFrames=Math.max(1,total/count);float phase=(frame%sceneFrames)/(float)sceneFrames;Bitmap source=images.get(index);drawImage(source,index,phase);paint.setColor(0xA0000000);canvas.drawRect(0,0,WIDTH,HEIGHT,paint);paint.setColor(0x52000000);canvas.drawRect(0,HEIGHT/2,WIDTH,HEIGHT,paint);
            String heading=index==0?"สินค้าใหม่":index==1||index==2||index==3?"จุดเด่น":index==4?"วิธีใช้":index==5?"ข้อควรรู้":"เพิ่มเติม";drawTextBlock(heading,safeX,safeTop,WIDTH-safeX*2,1,28,Color.rgb(231,165,93));
            String body=sceneText(index);drawTextBlock(index==0?name:body,safeX,HEIGHT-390,WIDTH-safeX*2,3,index==0?50:38,Color.WHITE);
            if(index==0){drawTextBlock(body,safeX,HEIGHT-190,WIDTH-safeX*2,2,30,Color.WHITE);paint.setColor(Color.rgb(231,165,93));paint.setTextSize(48);paint.setTypeface(Typeface.DEFAULT_BOLD);paint.setTextAlign(Paint.Align.LEFT);canvas.drawText("฿"+price,safeX,HEIGHT-safeBottom,paint);}else if(index>=6){paint.setColor(Color.rgb(231,165,93));paint.setTextSize(36);paint.setTypeface(Typeface.DEFAULT_BOLD);paint.setTextAlign(Paint.Align.LEFT);canvas.drawText("฿"+price,safeX,HEIGHT-safeBottom,paint);}
            GLES20.glViewport(0,0,WIDTH,HEIGHT);GLES20.glClear(GLES20.GL_COLOR_BUFFER_BIT);GLES20.glUseProgram(program);GLES20.glBindTexture(GLES20.GL_TEXTURE_2D,texture);GLUtils.texImage2D(GLES20.GL_TEXTURE_2D,0,frameBitmap,0);vertices.clear();vertices.put(new float[]{-1,-1,1,-1,-1,1,1,1}).position(0);texCoords.clear();texCoords.put(new float[]{0,1,1,1,0,0,1,0}).position(0);int ap=GLES20.glGetAttribLocation(program,"a"),tp=GLES20.glGetAttribLocation(program,"t");GLES20.glEnableVertexAttribArray(ap);GLES20.glEnableVertexAttribArray(tp);GLES20.glVertexAttribPointer(ap,2,GLES20.GL_FLOAT,false,0,vertices);GLES20.glVertexAttribPointer(tp,2,GLES20.GL_FLOAT,false,0,texCoords);GLES20.glDrawArrays(GLES20.GL_TRIANGLE_STRIP,0,4);GLES20.glDisableVertexAttribArray(ap);GLES20.glDisableVertexAttribArray(tp);EGLExt.eglPresentationTimeANDROID(display,eglSurface,frame*1000000000L/FPS);EGL14.eglSwapBuffers(display,eglSurface);}
        void release(){for(Bitmap b:images)b.recycle();frameBitmap.recycle();EGL14.eglMakeCurrent(display,EGL14.EGL_NO_SURFACE,EGL14.EGL_NO_SURFACE,EGL14.EGL_NO_CONTEXT);EGL14.eglDestroySurface(display,eglSurface);EGL14.eglDestroyContext(display,eglContext);EGL14.eglTerminate(display);}
    }
}
